import{_ as t,a as o,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 22 Give me a ... Which one?","description":"学习 which 与 one 的替代，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 22 Give me a ... Which one?","description":"学习 which 与 one 的替代，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 which 与 one 的替代，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 21 Which book?","link":"/life/english/new-concept/book-1/unit-01/lesson-021"},"next":{"text":"第一册：英语初阶 · Lesson 23 Which glasses?","link":"/life/english/new-concept/book-1/unit-01/lesson-023"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 21 Which book?","link":"/life/english/new-concept/book-1/unit-01/lesson-021"},"next":{"text":"第一册：英语初阶 · Lesson 23 Which glasses?","link":"/life/english/new-concept/book-1/unit-01/lesson-023"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-022.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-022.md"}'),i={name:"life/english/new-concept/book-1/unit-01/lesson-022.md"};function h(l,e,r,s,c,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-22-give-me-a-which-one" tabindex="-1">第一册：英语初阶 · Lesson 22 Give me a ... Which one? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-22-give-me-a-which-one" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 22 Give me a ... Which one?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-021">配套课 Lesson 21</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从多个单数物品中指定一个 本课要掌握which 与 one 的替代，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>which</td><td>/wɪtʃ/</td><td>限定词</td><td>哪一个</td><td>which notebook</td></tr><tr><td>give</td><td>/ɡɪv/</td><td>v.</td><td>给</td><td>give me a pen</td></tr><tr><td>one</td><td>/wʌn/</td><td>pron.</td><td>一个（替代物）</td><td>the red one</td></tr><tr><td>empty</td><td>/ˈempti/</td><td>adj.</td><td>空的</td><td>an empty box</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>give me — 给我，me 是宾格</li><li>the red one — 避免重复单数名词</li></ul><h2 id="语法讲解-which-与-one-的替代" tabindex="-1">语法讲解：which 与 one 的替代 <a class="header-anchor" href="#语法讲解-which-与-one-的替代" aria-label="Permalink to &quot;语法讲解：which 与 one 的替代&quot;">​</a></h2><p>which 用于在可识别的范围中选择。one 可以替代前面已提到的单数可数名词，以避免重复；如 the red one 表示红色的那个。give 可接双宾语：give + 人 + 物，人的位置用宾格。形容词前是否加 the 取决于是否指向特定选项，不是所有 one 都必须带 the。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Which notebook do you want: the red one or the blue one?</p></blockquote><p>你要哪本笔记本：红的还是蓝的？</p><p>Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>one 替代可数名词单数，不能用来替代不可数的 water。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Which notebook do you want: the red one or the blue one?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Which notebook do you want: the red one or the blue one? Please give me the empty box.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“从多个单数物品中指定一个”写两至三句，再读给同伴听。至少使用一次which 与 one 的替代，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。 Please 表礼貌；give 是祈使句谓语，me 为间接宾语，the empty box 为直接宾语；empty 修饰 box。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补替代词：the red notebook → the red ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> one</p><p><strong>解析：</strong> 按本课规则判断：which 用于在可识别的范围中选择。one 可以替代前面已提到的单数可数名词，以避免重复；如 the red one 表示红色的那个。give 可接双宾语：give + 人 + 物，人的位置用宾格。形容词前是否加 the 取决于是否指向特定选项，不是所有 one 都必须带 the。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“你要哪本笔记本：红的还是蓝的？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Which notebook do you want: the red one or the blue one?</p><p><strong>解析：</strong> Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Please give me the empty box.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 请把那个空盒子给我。</p><p><strong>解析：</strong> Please 表礼貌；give 是祈使句谓语，me 为间接宾语，the empty box 为直接宾语；empty 修饰 box。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：which 与 one 的替代。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-021">上一课</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-023">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",h]]);export{u as __pageData,b as default};
